internal sealed class FilterState<T1, T2, T3, T4>
    where T1 : struct where T2 : struct where T3 : struct where T4 : struct
{
    public Column<T1>? Col1; public Column<T2>? Col2; public Column<T3>? Col3; public Column<T4>? Col4;
    public SparseStorage<T1>? Sparse1; public SparseStorage<T2>? Sparse2; public SparseStorage<T3>? Sparse3; public SparseStorage<T4>? Sparse4;
    public int Shared1, Shared2, Shared3, Shared4;
    public Bitset? Bs1, Bs2, Bs3, Bs4;
    public Table? CurTable;

    [ThreadStatic] private static Stack<FilterState<T1, T2, T3, T4>>? _pool;

    public static FilterState<T1, T2, T3, T4> Rent()
    {
        var p = _pool ??= new Stack<FilterState<T1, T2, T3, T4>>(4);
        return p.Count > 0 ? p.Pop() : new FilterState<T1, T2, T3, T4>();
    }
    public static void Return(FilterState<T1, T2, T3, T4> f)
    {
        f.Col1 = null; f.Col2 = null; f.Col3 = null; f.Col4 = null; f.Bs1 = null; f.Bs2 = null; f.Bs3 = null; f.Bs4 = null; f.Sparse1 = null; f.Sparse2 = null; f.Sparse3 = null; f.Sparse4 = null; f.CurTable = null;
        _pool!.Push(f);
    }
}


