        var ids = new[] {
            (Id)w.Component<T1>(), (Id)w.Component<T2>(), (Id)w.Component<T3>(), (Id)w.Component<T4>(), (Id)w.Component<T5>(), (Id)w.Component<T6>()
        };
        Id[] result = Array.Empty<Id>();
        for (int i = 0; i < ids.Length; i++) result = QueryUtil.AppendSorted(result, ids[i]);
        return result;
    }

    internal Query(World w) : base(w, BuildWith(w))
    {
        _c1 = (Id)w.Component<T1>();
        _c2 = (Id)w.Component<T2>();
        _c3 = (Id)w.Component<T3>();
        _c4 = (Id)w.Component<T4>();
        _c5 = (Id)w.Component<T5>();
        _c6 = (Id)w.Component<T6>();
    }

    public Query<T1, T2, T3, T4, T5, T6> With<T>() where T : struct { AddWith(_world.IdOf<T>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6> With<TR, TT>() where TR : struct where TT : struct { AddWith(_world.Pair<TR, TT>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6> With<TR>(EntityId target) where TR : struct { AddWith(_world.Pair(_world.Component<TR>(), target)); return this; }
    public Query<T1, T2, T3, T4, T5, T6> With(EntityId relation, EntityId target) { AddWith(_world.Pair(relation, target)); return this; }
    public Query<T1, T2, T3, T4, T5, T6> With(Id id) { AddWith(id); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Without<T>() where T : struct { AddWithout(_world.IdOf<T>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Without<TR, TT>() where TR : struct where TT : struct { AddWithout(_world.Pair<TR, TT>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Without<TR>(EntityId target) where TR : struct { AddWithout(_world.Pair(_world.Component<TR>(), target)); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Without(EntityId relation, EntityId target) { AddWithout(_world.Pair(relation, target)); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Without(Id id) { AddWithout(id); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Or<TA, TB>() where TA : struct where TB : struct
    { AddOr(new[] { _world.IdOf<TA>(), _world.IdOf<TB>() }); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Or<TA, TB, TC>() where TA : struct where TB : struct where TC : struct
    { AddOr(new[] { _world.IdOf<TA>(), _world.IdOf<TB>(), _world.IdOf<TC>() }); return this; }

    // Mark a typed slot as optional. Match ignores it; RowEnumerator yields
    // Unsafe.NullRef<T>() for absent rows. Caller checks via Unsafe.IsNullRef.
    public Query<T1, T2, T3, T4, T5, T6> Optional<T>() where T : struct
    {
        if (typeof(T) == typeof(T1)) { if (!_t1Optional) { _t1Optional = true; _with = QueryUtil.Remove(_with, _c1); Reset(); } return this; }
        if (typeof(T) == typeof(T2)) { if (!_t2Optional) { _t2Optional = true; _with = QueryUtil.Remove(_with, _c2); Reset(); } return this; }
        if (typeof(T) == typeof(T3)) { if (!_t3Optional) { _t3Optional = true; _with = QueryUtil.Remove(_with, _c3); Reset(); } return this; }
        if (typeof(T) == typeof(T4)) { if (!_t4Optional) { _t4Optional = true; _with = QueryUtil.Remove(_with, _c4); Reset(); } return this; }
        if (typeof(T) == typeof(T5)) { if (!_t5Optional) { _t5Optional = true; _with = QueryUtil.Remove(_with, _c5); Reset(); } return this; }
        if (typeof(T) == typeof(T6)) { if (!_t6Optional) { _t6Optional = true; _with = QueryUtil.Remove(_with, _c6); Reset(); } return this; }
        ThrowHelper.OptionalTypeMismatch(typeof(T), "T1, T2, T3, T4, T5, or T6");
        return this;
    }

    public Query<T1, T2, T3, T4, T5, T6> Inherited() { SetInherited(); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Read<T>() where T : struct { MarkRead(_world.IdOf<T>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Write<T>() where T : struct { MarkWrite(_world.IdOf<T>()); return this; }

    public Query<T1, T2, T3, T4, T5, T6> Up<T>() where T : struct
    { SetTermTraversal(_world.IdOf<T>(), _world.IsA.Id, -1); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Up<T>(EntityId relation) where T : struct
    { SetTermTraversal(_world.IdOf<T>(), relation.Id, -1); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Parent<T>() where T : struct
    { SetTermTraversal(_world.IdOf<T>(), _world.ChildOf.Id, 1); return this; }
    public Query<T1, T2, T3, T4, T5, T6> Cascade<T>() where T : struct
    {
        SetTermTraversal(_world.IdOf<T>(), _world.ChildOf.Id, -1);
        SetCascade(_world.ChildOf.Id);
        return this;
    }
    public Query<T1, T2, T3, T4, T5, T6> Cascade<T>(EntityId relation) where T : struct
    {
        SetTermTraversal(_world.IdOf<T>(), relation.Id, -1);
        SetCascade(relation.Id);
        return this;
    }
    // Reverse cascade — descendants before ancestors. No-op without Cascade.
    public Query<T1, T2, T3, T4, T5, T6> Desc() { SetCascadeDesc(); return this; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public RowEnumerator<T1, T2, T3, T4, T5, T6> GetEnumerator() => new(this);

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public RowEnumerator<T1, T2, T3, T4, T5, T6> Rows() => new(this);
}


public ref struct RowEnumerator<T1, T2, T3, T4, T5, T6>
    where T1 : struct where T2 : struct where T3 : struct where T4 : struct where T5 : struct where T6 : struct
{
    private readonly Query<T1, T2, T3, T4, T5, T6> _query;
    private readonly bool _hasFilter;
    private ReadonlyScope _defer;
    private int _tableIdx;
    private int _rowIdx;
    private int _count;
    private bool _disposed;
    private Ptr<T1> _ptr1;
    private Ptr<T2> _ptr2;
    private Ptr<T3> _ptr3;
    private Ptr<T4> _ptr4;
    private Ptr<T5> _ptr5;
    private Ptr<T6> _ptr6;
    private FilterState<T1, T2, T3, T4, T5, T6>? _filter;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal RowEnumerator(Query<T1, T2, T3, T4, T5, T6> q)
    {
        _query = q;
        if (q._world._anyUnion) q.EnsureUnionWith();
        _hasFilter = q._anyInheritance || q._t1Optional || q._t2Optional || q._t3Optional || q._t4Optional || q._t5Optional || q._t6Optional
            || (q._world._anyCanToggle && (q._world.IsCanToggleId(q._c1) || q._world.IsCanToggleId(q._c2) || q._world.IsCanToggleId(q._c3) || q._world.IsCanToggleId(q._c4) || q._world.IsCanToggleId(q._c5) || q._world.IsCanToggleId(q._c6)))
            || (q._world._anySparse && (q._world.IsSparseId(q._c1) || q._world.IsSparseId(q._c2) || q._world.IsSparseId(q._c3) || q._world.IsSparseId(q._c4) || q._world.IsSparseId(q._c5) || q._world.IsSparseId(q._c6)))
            || (q._world._anyUnion && q.HasUnionWith);
        _filter = _hasFilter ? FilterState<T1, T2, T3, T4, T5, T6>.Rent() : null;
        _defer = q._world.Readonly();
        q.Rematch();
        _tableIdx = -1;
        _rowIdx = -1;
        _count = 0;
        _disposed = false;
    }

    public RowEnumerator<T1, T2, T3, T4, T5, T6> Current
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        get => this;
    }
    public Ptr<T1> Component1 { [MethodImpl(MethodImplOptions.AggressiveInlining)] get => _ptr1; }
    public Ptr<T2> Component2 { [MethodImpl(MethodImplOptions.AggressiveInlining)] get => _ptr2; }
    public Ptr<T3> Component3 { [MethodImpl(MethodImplOptions.AggressiveInlining)] get => _ptr3; }
    public Ptr<T4> Component4 { [MethodImpl(MethodImplOptions.AggressiveInlining)] get => _ptr4; }
    public Ptr<T5> Component5 { [MethodImpl(MethodImplOptions.AggressiveInlining)] get => _ptr5; }
    public Ptr<T6> Component6 { [MethodImpl(MethodImplOptions.AggressiveInlining)] get => _ptr6; }
    public EntityId Entity
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        get => (_filter?.CurTable ?? _query._matched[_tableIdx]).Entities[_rowIdx];
    }
    public bool IsShared1 => _filter is { Shared1: >= 0 };
    public bool IsShared2 => _filter is { Shared2: >= 0 };
    public bool IsShared3 => _filter is { Shared3: >= 0 };
    public bool IsShared4 => _filter is { Shared4: >= 0 };
    public bool IsShared5 => _filter is { Shared5: >= 0 };
    public bool IsShared6 => _filter is { Shared6: >= 0 };

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public readonly void Deconstruct(out Ptr<T1> p1, out Ptr<T2> p2, out Ptr<T3> p3, out Ptr<T4> p4, out Ptr<T5> p5, out Ptr<T6> p6)
    { p1 = _ptr1; p2 = _ptr2; p3 = _ptr3; p4 = _ptr4; p5 = _ptr5; p6 = _ptr6; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public readonly void Deconstruct(out EntityId entity, out Ptr<T1> p1, out Ptr<T2> p2, out Ptr<T3> p3, out Ptr<T4> p4, out Ptr<T5> p5, out Ptr<T6> p6)
    { entity = (_filter?.CurTable ?? _query._matched[_tableIdx]).Entities[_rowIdx]; p1 = _ptr1; p2 = _ptr2; p3 = _ptr3; p4 = _ptr4; p5 = _ptr5; p6 = _ptr6; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool MoveNext()
    {
        if (++_rowIdx < _count)
        {
            if (!_hasFilter)
            {
                _ptr1.Value = ref Unsafe.Add(ref _ptr1.Value, 1);
                _ptr2.Value = ref Unsafe.Add(ref _ptr2.Value, 1);
                _ptr3.Value = ref Unsafe.Add(ref _ptr3.Value, 1);
                _ptr4.Value = ref Unsafe.Add(ref _ptr4.Value, 1);
                _ptr5.Value = ref Unsafe.Add(ref _ptr5.Value, 1);
                _ptr6.Value = ref Unsafe.Add(ref _ptr6.Value, 1);
                return true;
            }
            if (AdvanceFiltered()) return true;
        }
        return MoveNextSlow();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private bool AdvanceFiltered()
    {
        var f = _filter!;
        while (_rowIdx < _count)
        {
            uint entId = f.CurTable!.Entities[_rowIdx].Id;
            if (_query.HasUnionWith && !_query.MatchesUnionWith(entId)) { _rowIdx++; continue; }
            if (f.Sparse1 != null) { if (!f.Sparse1.Has(entId)) { _rowIdx++; continue; } } else if (f.Bs1 != null && !f.Bs1.Get(_rowIdx)) { _rowIdx++; continue; }
            if (f.Sparse2 != null) { if (!f.Sparse2.Has(entId)) { _rowIdx++; continue; } } else if (f.Bs2 != null && !f.Bs2.Get(_rowIdx)) { _rowIdx++; continue; }
            if (f.Sparse3 != null) { if (!f.Sparse3.Has(entId)) { _rowIdx++; continue; } } else if (f.Bs3 != null && !f.Bs3.Get(_rowIdx)) { _rowIdx++; continue; }
            if (f.Sparse4 != null) { if (!f.Sparse4.Has(entId)) { _rowIdx++; continue; } } else if (f.Bs4 != null && !f.Bs4.Get(_rowIdx)) { _rowIdx++; continue; }
            if (f.Sparse5 != null) { if (!f.Sparse5.Has(entId)) { _rowIdx++; continue; } } else if (f.Bs5 != null && !f.Bs5.Get(_rowIdx)) { _rowIdx++; continue; }
            if (f.Sparse6 != null) { if (!f.Sparse6.Has(entId)) { _rowIdx++; continue; } } else if (f.Bs6 != null && !f.Bs6.Get(_rowIdx)) { _rowIdx++; continue; }
            if (f.Sparse1 != null) _ptr1.Value = ref f.Sparse1.GetRef(entId); else _ptr1.Value = ref RowEnumeratorUtil.Resolve(f.Col1, f.Shared1, _rowIdx);
            if (f.Sparse2 != null) _ptr2.Value = ref f.Sparse2.GetRef(entId); else _ptr2.Value = ref RowEnumeratorUtil.Resolve(f.Col2, f.Shared2, _rowIdx);
            if (f.Sparse3 != null) _ptr3.Value = ref f.Sparse3.GetRef(entId); else _ptr3.Value = ref RowEnumeratorUtil.Resolve(f.Col3, f.Shared3, _rowIdx);
            if (f.Sparse4 != null) _ptr4.Value = ref f.Sparse4.GetRef(entId); else _ptr4.Value = ref RowEnumeratorUtil.Resolve(f.Col4, f.Shared4, _rowIdx);
            if (f.Sparse5 != null) _ptr5.Value = ref f.Sparse5.GetRef(entId); else _ptr5.Value = ref RowEnumeratorUtil.Resolve(f.Col5, f.Shared5, _rowIdx);
            if (f.Sparse6 != null) _ptr6.Value = ref f.Sparse6.GetRef(entId); else _ptr6.Value = ref RowEnumeratorUtil.Resolve(f.Col6, f.Shared6, _rowIdx);
            return true;
        }
        return false;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private bool MoveNextSlow()
    {
        var matched = CollectionsMarshal.AsSpan(_query._matched);
        var w = _query._world;
        while (true)
        {
            _tableIdx++;
            if (_tableIdx >= matched.Length) return false;
            var t = matched[_tableIdx];
            int n = t.Count;
            if (n == 0) continue;
            if (!_hasFilter)
            {
                var c1 = (Column<T1>)t.Columns[t.IndexOf(_query._c1)]!;
                var c2 = (Column<T2>)t.Columns[t.IndexOf(_query._c2)]!;
                var c3 = (Column<T3>)t.Columns[t.IndexOf(_query._c3)]!;
                var c4 = (Column<T4>)t.Columns[t.IndexOf(_query._c4)]!;
                var c5 = (Column<T5>)t.Columns[t.IndexOf(_query._c5)]!;
                var c6 = (Column<T6>)t.Columns[t.IndexOf(_query._c6)]!;
                _ptr1.Value = ref MemoryMarshal.GetReference(c1.AsSpan());
                _ptr2.Value = ref MemoryMarshal.GetReference(c2.AsSpan());
                _ptr3.Value = ref MemoryMarshal.GetReference(c3.AsSpan());
                _ptr4.Value = ref MemoryMarshal.GetReference(c4.AsSpan());
                _ptr5.Value = ref MemoryMarshal.GetReference(c5.AsSpan());
                _ptr6.Value = ref MemoryMarshal.GetReference(c6.AsSpan());
                _count = n;
                _rowIdx = 0;
                return true;
            }
            var f = _filter!;
            f.CurTable = t;
            bool skip = false;
            if (w.IsSparseId(_query._c1)) { f.Sparse1 = (SparseStorage<T1>)w._sparseStorage[_query._c1.Component]; f.Col1 = null; f.Shared1 = -1; f.Bs1 = null; }
            else { f.Sparse1 = null; var (c, s) = _query.ResolveSource<T1>(t, _query._c1); if (c == null && !_query._t1Optional) skip = true; else { f.Col1 = c; f.Shared1 = s; f.Bs1 = _query.ResolveBitset(t, _query._c1, s); } }
            if (skip) continue;
            if (w.IsSparseId(_query._c2)) { f.Sparse2 = (SparseStorage<T2>)w._sparseStorage[_query._c2.Component]; f.Col2 = null; f.Shared2 = -1; f.Bs2 = null; }
            else { f.Sparse2 = null; var (c, s) = _query.ResolveSource<T2>(t, _query._c2); if (c == null && !_query._t2Optional) skip = true; else { f.Col2 = c; f.Shared2 = s; f.Bs2 = _query.ResolveBitset(t, _query._c2, s); } }
            if (skip) continue;
            if (w.IsSparseId(_query._c3)) { f.Sparse3 = (SparseStorage<T3>)w._sparseStorage[_query._c3.Component]; f.Col3 = null; f.Shared3 = -1; f.Bs3 = null; }
            else { f.Sparse3 = null; var (c, s) = _query.ResolveSource<T3>(t, _query._c3); if (c == null && !_query._t3Optional) skip = true; else { f.Col3 = c; f.Shared3 = s; f.Bs3 = _query.ResolveBitset(t, _query._c3, s); } }
            if (skip) continue;
            if (w.IsSparseId(_query._c4)) { f.Sparse4 = (SparseStorage<T4>)w._sparseStorage[_query._c4.Component]; f.Col4 = null; f.Shared4 = -1; f.Bs4 = null; }
            else { f.Sparse4 = null; var (c, s) = _query.ResolveSource<T4>(t, _query._c4); if (c == null && !_query._t4Optional) skip = true; else { f.Col4 = c; f.Shared4 = s; f.Bs4 = _query.ResolveBitset(t, _query._c4, s); } }
            if (skip) continue;
            if (w.IsSparseId(_query._c5)) { f.Sparse5 = (SparseStorage<T5>)w._sparseStorage[_query._c5.Component]; f.Col5 = null; f.Shared5 = -1; f.Bs5 = null; }
            else { f.Sparse5 = null; var (c, s) = _query.ResolveSource<T5>(t, _query._c5); if (c == null && !_query._t5Optional) skip = true; else { f.Col5 = c; f.Shared5 = s; f.Bs5 = _query.ResolveBitset(t, _query._c5, s); } }
            if (skip) continue;
            if (w.IsSparseId(_query._c6)) { f.Sparse6 = (SparseStorage<T6>)w._sparseStorage[_query._c6.Component]; f.Col6 = null; f.Shared6 = -1; f.Bs6 = null; }
            else { f.Sparse6 = null; var (c, s) = _query.ResolveSource<T6>(t, _query._c6); if (c == null && !_query._t6Optional) skip = true; else { f.Col6 = c; f.Shared6 = s; f.Bs6 = _query.ResolveBitset(t, _query._c6, s); } }
            if (skip) continue;
            _count = n;
            _rowIdx = 0;
            if (AdvanceFiltered()) return true;
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public RowEnumerator<T1, T2, T3, T4, T5, T6> GetEnumerator() => this;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        if (_filter != null) FilterState<T1, T2, T3, T4, T5, T6>.Return(_filter);
        _query.MarkObserved();
        _defer.Dispose();
    }
}


internal sealed class FilterState<T1, T2, T3, T4, T5, T6, T7>
    where T1 : struct where T2 : struct where T3 : struct where T4 : struct where T5 : struct where T6 : struct where T7 : struct
{
    public Column<T1>? Col1; public Column<T2>? Col2; public Column<T3>? Col3; public Column<T4>? Col4; public Column<T5>? Col5; public Column<T6>? Col6; public Column<T7>? Col7;
    public SparseStorage<T1>? Sparse1; public SparseStorage<T2>? Sparse2; public SparseStorage<T3>? Sparse3; public SparseStorage<T4>? Sparse4; public SparseStorage<T5>? Sparse5; public SparseStorage<T6>? Sparse6; public SparseStorage<T7>? Sparse7;
    public int Shared1, Shared2, Shared3, Shared4, Shared5, Shared6, Shared7;
    public Bitset? Bs1, Bs2, Bs3, Bs4, Bs5, Bs6, Bs7;
    public Table? CurTable;

    [ThreadStatic] private static Stack<FilterState<T1, T2, T3, T4, T5, T6, T7>>? _pool;

    public static FilterState<T1, T2, T3, T4, T5, T6, T7> Rent()
    {
        var p = _pool ??= new Stack<FilterState<T1, T2, T3, T4, T5, T6, T7>>(4);
        return p.Count > 0 ? p.Pop() : new FilterState<T1, T2, T3, T4, T5, T6, T7>();
    }
    public static void Return(FilterState<T1, T2, T3, T4, T5, T6, T7> f)
    {
        f.Col1 = null; f.Col2 = null; f.Col3 = null; f.Col4 = null; f.Col5 = null; f.Col6 = null; f.Col7 = null; f.Bs1 = null; f.Bs2 = null; f.Bs3 = null; f.Bs4 = null; f.Bs5 = null; f.Bs6 = null; f.Bs7 = null; f.Sparse1 = null; f.Sparse2 = null; f.Sparse3 = null; f.Sparse4 = null; f.Sparse5 = null; f.Sparse6 = null; f.Sparse7 = null; f.CurTable = null;
        _pool!.Push(f);
    }
}


public sealed class Query<T1, T2, T3, T4, T5, T6, T7> : QueryBase
    where T1 : struct where T2 : struct where T3 : struct where T4 : struct where T5 : struct where T6 : struct where T7 : struct
{
    internal readonly Id _c1, _c2, _c3, _c4, _c5, _c6, _c7;
    internal bool _t1Optional, _t2Optional, _t3Optional, _t4Optional, _t5Optional, _t6Optional, _t7Optional;

    private static Id[] BuildWith(World w)
    {
        var ids = new[] {
            (Id)w.Component<T1>(), (Id)w.Component<T2>(), (Id)w.Component<T3>(), (Id)w.Component<T4>(), (Id)w.Component<T5>(), (Id)w.Component<T6>(), (Id)w.Component<T7>()
        };
        Id[] result = Array.Empty<Id>();
        for (int i = 0; i < ids.Length; i++) result = QueryUtil.AppendSorted(result, ids[i]);
        return result;
    }

    internal Query(World w) : base(w, BuildWith(w))
    {
        _c1 = (Id)w.Component<T1>();
        _c2 = (Id)w.Component<T2>();
        _c3 = (Id)w.Component<T3>();
        _c4 = (Id)w.Component<T4>();
        _c5 = (Id)w.Component<T5>();
        _c6 = (Id)w.Component<T6>();
        _c7 = (Id)w.Component<T7>();
    }

    public Query<T1, T2, T3, T4, T5, T6, T7> With<T>() where T : struct { AddWith(_world.IdOf<T>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> With<TR, TT>() where TR : struct where TT : struct { AddWith(_world.Pair<TR, TT>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> With<TR>(EntityId target) where TR : struct { AddWith(_world.Pair(_world.Component<TR>(), target)); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> With(EntityId relation, EntityId target) { AddWith(_world.Pair(relation, target)); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> With(Id id) { AddWith(id); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> Without<T>() where T : struct { AddWithout(_world.IdOf<T>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> Without<TR, TT>() where TR : struct where TT : struct { AddWithout(_world.Pair<TR, TT>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> Without<TR>(EntityId target) where TR : struct { AddWithout(_world.Pair(_world.Component<TR>(), target)); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> Without(EntityId relation, EntityId target) { AddWithout(_world.Pair(relation, target)); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> Without(Id id) { AddWithout(id); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> Or<TA, TB>() where TA : struct where TB : struct
    { AddOr(new[] { _world.IdOf<TA>(), _world.IdOf<TB>() }); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7> Or<TA, TB, TC>() where TA : struct where TB : struct where TC : struct
    { AddOr(new[] { _world.IdOf<TA>(), _world.IdOf<TB>(), _world.IdOf<TC>() }); return this; }

    // Mark a typed slot as optional. Match ignores it; RowEnumerator yields
