            (Id)w.Component<T1>(), (Id)w.Component<T2>(), (Id)w.Component<T3>(), (Id)w.Component<T4>(), (Id)w.Component<T5>(), (Id)w.Component<T6>(), (Id)w.Component<T7>(), (Id)w.Component<T8>(), (Id)w.Component<T9>()
